-- Founder-owned connection provisioning. Plaintext credentials never enter a public ledger.
begin;
create table public.provider_account_connections(id uuid primary key default gen_random_uuid(),mission_id uuid not null references public.missions(id),account_id uuid not null references public.founder_accounts(id),counterparty_id uuid references public.counterparties(id),provider text not null,sandbox_mode boolean not null,verification jsonb not null,ownership text not null check(ownership='founder_attested'),created_at timestamptz not null default clock_timestamp(),unique(mission_id,id),unique(account_id));
alter table public.provider_account_connections enable row level security;alter table public.provider_account_connections force row level security;
create policy tenant_scope on public.provider_account_connections using(private.owns_mission(mission_id))with check(private.owns_mission(mission_id));
create trigger immutable_row before update or delete on public.provider_account_connections for each row execute function private.immutable_row();
grant select on public.provider_account_connections to founder_role,policy_role,lead_role,specialist_role;
create function public.connect_provider_account(p_mission uuid,p_provider text,p_scopes text[],p_ref uuid,p_encrypted jsonb,p_verification jsonb,p_party uuid default null,p_label text default null)returns uuid language plpgsql security definer set search_path=''as $$declare v_account uuid;v_founder uuid;v_sandbox boolean;begin
  perform private.require_role(array['founder_role']);perform private.lock_mission(p_mission);select founder_id,sandbox_mode into strict v_founder,v_sandbox from public.missions where id=p_mission;
  if p_provider not in('paypal','twilio','resend','shopify','browserbase','openai')or not(p_encrypted?&array['iv','ciphertext','tag'])or p_verification->>'status'not in('authenticated','unverified')or p_verification->>'ownership'<>'founder_attested'then raise exception 'validation: provider connection contract invalid';end if;
  perform private.assert_safe_content(p_verification);
  if p_provider='shopify'then if p_party is null or length(p_label)=0 then raise exception 'validation: store identity required';end if;insert into public.counterparties(id,founder_id,kind,name,verification)values(p_party,v_founder,'service',left(p_label,200),'{"ownership":"founder_attested","type":"store"}');end if;
  insert into public.founder_accounts(founder_id,provider,status,scopes)values(v_founder,p_provider,'connected',p_scopes)returning id into v_account;
  insert into private.provider_credentials(ref,mission_id,account_id,provider,sandbox_mode,encrypted)values(p_ref,p_mission,v_account,p_provider,v_sandbox,p_encrypted);
  insert into public.provider_account_connections(mission_id,account_id,counterparty_id,provider,sandbox_mode,verification,ownership)values(p_mission,v_account,p_party,p_provider,v_sandbox,p_verification,'founder_attested');
  insert into public.outbox(mission_id,type,payload)values(p_mission,'account.connected',jsonb_build_object('accountId',v_account,'provider',p_provider,'verificationStatus',p_verification->>'status'));return v_account;
end$$;
create table private.shopify_oauth_states(id uuid primary key,mission_id uuid not null references public.missions(id),auth_user_id uuid not null,state_hash text not null unique,shop_domain text not null,expires_at timestamptz not null,created_at timestamptz not null default clock_timestamp());
create table private.shopify_oauth_consumptions(state_id uuid primary key references private.shopify_oauth_states(id),created_at timestamptz not null default clock_timestamp());
create function public.create_shopify_oauth_state(p_mission uuid,p_hash text,p_shop text)returns uuid language plpgsql security definer set search_path=''as $$declare v_id uuid;begin perform private.require_role(array['founder_role']);perform private.lock_mission(p_mission);if p_hash!~'^[a-f0-9]{64}$'or p_shop!~'^[a-z0-9][a-z0-9-]*\.myshopify\.com$'then raise exception 'validation: invalid OAuth state';end if;v_id:=gen_random_uuid();insert into private.shopify_oauth_states values(v_id,p_mission,private.actor_id(),p_hash,p_shop,clock_timestamp()+interval'10 minutes',clock_timestamp());return v_id;end$$;
create function public.consume_shopify_oauth_state(p_mission uuid,p_hash text,p_shop text)returns uuid language plpgsql security definer set search_path=''as $$declare v_id uuid;begin perform private.require_role(array['founder_role']);perform private.lock_mission(p_mission);select id into strict v_id from private.shopify_oauth_states where mission_id=p_mission and auth_user_id=private.actor_id()and state_hash=p_hash and shop_domain=p_shop and expires_at>clock_timestamp()for update;insert into private.shopify_oauth_consumptions(state_id)values(v_id);return v_id;end$$;
revoke execute on function public.connect_provider_account(uuid,text,text[],uuid,jsonb,jsonb,uuid,text),public.create_shopify_oauth_state(uuid,text,text),public.consume_shopify_oauth_state(uuid,text,text)from public;
grant execute on function public.connect_provider_account(uuid,text,text[],uuid,jsonb,jsonb,uuid,text),public.create_shopify_oauth_state(uuid,text,text),public.consume_shopify_oauth_state(uuid,text,text)to founder_role;
commit;
